class Store { constructor(){this.m=new Map()} k(o,k,i){return `${o}:${k}:${i}`} async get(o,k,i){return this.m.get(this.k(o,k,i))??null} async put(o,k,v){this.m.set(this.k(o,k,v.id),v);return v} async insertIfAbsent(o,k,v){let x=this.k(o,k,v.id);if(this.m.has(x))return null;this.m.set(x,v);return v} async claimStatus(o,k,i,e,n){let x=this.k(o,k,i),v=this.m.get(x);if(!v||v.status!==e)return null;let q={...v,status:n};this.m.set(x,q);return q} async list(o,k){return [...this.m.values()].filter(v=>v.owner===o)} }
