const budget=await cp.budget('u',{scope:'run',used:9,limit:10});if(!budget.allowed||budget.remaining!==1)throw new Error('budget failed');
console.log('splus-smoke=ok',{grant:grant.id,first:first.status,second:second.status,remaining:budget.remaining});
